<template>
    <div>
        <Head title="Regular Tables" />

        <Card
            v-for="table in examples"
            :key="table.title"
            :class="{ 'card-plain': table.plain }"
            icon="assignment"
            card-header-class="card-header-rose"
            :card-body-class="table.colored ? 'table-full-width' : undefined"
        >
            <template #header>
                <h4 class="card-title" :class="{ 'mt-0': table.plain }">{{ table.title }}</h4>
                <p v-if="table.plain" class="card-category">Here is a subtitle for this table</p>
            </template>

            <div class="table-responsive">
                <table class="table">
                    <caption class="visually-hidden">{{ table.title }}</caption>
                    <thead :class="{ 'text-primary': !table.plain && !table.colored }">
                        <tr>
                            <th v-for="column in columns" :key="column" scope="col">{{ column }}</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr
                            v-for="employee in table.colored ? coloredEmployees : employees"
                            :key="employee.id"
                            :class="table.colored ? employee.color : undefined"
                        >
                            <td>{{ employee.id }}</td>
                            <td>{{ employee.name }}</td>
                            <td>{{ employee.country }}</td>
                            <td>{{ employee.city }}</td>
                            <td>{{ employee.salary }}</td>
                        </tr>
                    </tbody>
                </table>
            </div>
        </Card>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';

export default {
    name: 'RegularTablesDemo',
    components: { Card, Head },
    layout: { pageTitle: 'Regular Tables' },
    data() {
        return {
            examples: [
                { title: 'Simple Table' },
                { title: 'Table on Plain Background', plain: true },
                { title: 'Regular Table with Colors', colored: true },
            ],
            columns: ['ID', 'Name', 'Country', 'City', 'Salary'],
            employees: [
                { id: 1, name: 'Dakota Rice', country: 'Niger', city: 'Oud-Turnhout', salary: '$36,738', color: 'table-success' },
                { id: 2, name: 'Minerva Hooper', country: 'Curaçao', city: 'Sinaai-Waas', salary: '$23,789' },
                { id: 3, name: 'Sage Rodriguez', country: 'Netherlands', city: 'Baileux', salary: '$56,142', color: 'table-info' },
                { id: 4, name: 'Philip Chaney', country: 'Korea, South', city: 'Overland Park', salary: '$38,735' },
                { id: 5, name: 'Doris Greene', country: 'Malawi', city: 'Feldkirchen in Kärnten', salary: '$63,542', color: 'table-danger' },
                { id: 6, name: 'Mason Porter', country: 'Chile', city: 'Gloucester', salary: '$78,615' },
            ],
        };
    },
    computed: {
        coloredEmployees() {
            return [
                ...this.employees,
                { id: 7, name: 'Jon Porter', country: 'Portugal', city: 'Gloucester', salary: '$98,615', color: 'table-warning' },
            ];
        },
    },
};
</script>
